package ch.zwiftfree.road;

import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/** Mapbox vector tiles of the road network, generated by PostGIS (ST_AsMVT) and cached in memory. */
@Service
public class TileService {

    /** Ticino in Web Mercator, with a margin: tiles outside are empty without asking the database. */
    private static final double MIN_X = 925_000, MAX_X = 1_025_000, MIN_Y = 5_740_000, MAX_Y = 5_880_000;
    private static final byte[] EMPTY = new byte[0];

    private final JdbcTemplate jdbc;
    private final RoadImportService importService;
    private final Cache<String, byte[]> cache;

    public TileService(JdbcTemplate jdbc, RoadImportService importService, RoadProperties props) {
        this.jdbc = jdbc;
        this.importService = importService;
        this.cache = Caffeine.newBuilder().maximumSize(props.tileCacheSize()).build();
    }

    public byte[] roads(int z, int x, int y) {
        if (z < 0 || z > 22 || x < 0 || y < 0 || x >= (1 << z) || y >= (1 << z)) {
            return EMPTY;
        }
        if (!intersectsTicino(z, x, y)) {
            return EMPTY;
        }
        return cache.get(z + "/" + x + "/" + y, k -> render(z, x, y));
    }

    @EventListener
    public void onImport(RoadNetworkImportedEvent event) {
        if (event.changed()) {
            cache.invalidateAll();
        }
    }

    private byte[] render(int z, int x, int y) {
        if (!importService.roadTablesPresent()) {
            return EMPTY;
        }
        // Low zooms: simplified view and only the more important roads.
        String table = z < 13 ? "road_edges_display" : "road_edges";
        int maxRank = z < 9 ? 2 : z < 10 ? 3 : z < 11 ? 4 : z < 12 ? 5 : 9;
        byte[] tile = jdbc.queryForObject("""
                WITH b AS (SELECT ST_TileEnvelope(?, ?, ?) AS env),
                mvt AS (
                    SELECT ST_AsMVTGeom(e.geom_3857, b.env, 4096, 64, true) AS geom,
                           e.id, e.name, e.highway, e.rank,
                           round(e.steepest::numeric, 1)::real AS steepest,
                           round(e.length_m::numeric)::int AS length_m,
                           round(e.ascent_m::numeric)::int AS ascent_m,
                           round(e.descent_m::numeric)::int AS descent_m,
                           e.oneway
                    FROM %s e, b
                    WHERE e.geom_3857 && b.env AND e.rank <= ?
                )
                SELECT ST_AsMVT(mvt.*, 'roads', 4096, 'geom', 'id') FROM mvt WHERE geom IS NOT NULL
                """.formatted(table), byte[].class, z, x, y, maxRank);
        return tile == null ? EMPTY : tile;
    }

    static boolean intersectsTicino(int z, int x, int y) {
        double size = 2 * 20037508.342789244 / (1 << z);
        double minX = -20037508.342789244 + x * size;
        double maxY = 20037508.342789244 - y * size;
        double maxX = minX + size;
        double minY = maxY - size;
        return maxX >= MIN_X && minX <= MAX_X && maxY >= MIN_Y && minY <= MAX_Y;
    }
}
